-- STAGIA / Subdivisions géographiques RDC v1.1.0 — MySQL 8.0+
-- Migration additive et idempotente : aucun DROP, aucun UPDATE des unités existantes.
SET NAMES utf8mb4;
START TRANSACTION;
SET @geo_avant := (SELECT COUNT(*) FROM geographie_unites);
UPDATE geographie_version SET revision=revision+1 WHERE id=1 AND (SELECT COUNT(*) FROM geographie_unites)>@geo_avant;
COMMIT;
